<script lang="ts">
 import {t} from '#lib/i18n.ts';
 import {onMount} from 'svelte';import {api,session,refreshSession} from '#lib/client.svelte.ts';import Icon from '#lib/components/Icon.svelte';import Modal from '#lib/components/Modal.svelte';import Bottle from '#lib/components/Bottle.svelte';
 let bottles=$state<any[]>([]);let loaded=$state(false);let open=$state(false);let busy=$state(false);let error=$state('');let id=$state('');let search=$state('');let deleteOpen=$state(false);
 const empty=()=>({name:'',producer:'',region:'',year:'',quantity:1,location:'',memo:'',style:'Weiß'});let form=$state(empty());
 const filtered=$derived(bottles.filter(b=>`${b.data.name} ${b.data.producer} ${b.data.region} ${b.data.location}`.toLowerCase().includes(search.toLowerCase())));
 const total=$derived(bottles.reduce((n,b)=>n+b.data.quantity,0));
 async function load(){try{const d=await api('cellar');bottles=d.bottles;}catch(e){error=(e as Error).message;}loaded=true;}
 onMount(async()=>{if(!session.loaded)await refreshSession();if(session.user)await load();else loaded=true;});
 function edit(b?:any){id=b?.id||'';form=b?{...b.data}:empty();error='';open=true;}
 async function save(){busy=true;error='';try{await api('cellar',{id:id||undefined,data:form});await load();open=false;}catch(e){error=(e as Error).message;}busy=false;}
 async function quantity(b:any,amount:number){if(busy)return;busy=true;error='';try{await api('cellar',{id:b.id,data:{...b.data,quantity:Math.max(0,b.data.quantity+amount)}});await load();}catch(e){error=(e as Error).message;}busy=false;}
 async function remove(){busy=true;error='';try{await api('cellar',{id},'DELETE');deleteOpen=false;open=false;await load();}catch(e){error=(e as Error).message;}busy=false;}
 function download(){const blob=new Blob([JSON.stringify(bottles,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='mein-weinkeller.json';a.click();URL.revokeObjectURL(a.href);}
</script>
<svelte:head><title>{t('m_24bd75b8ea')}</title></svelte:head>
<div class="page-content"><div class="page-heading"><div><div class="eyebrow">{t('m_e6fde1fc0d')}</div><h1>{t('m_3584780cee')}<span class="accent">.</span></h1><p>{t('m_261adb33b7')}</p></div>{#if session.user}<button class="button primary" onclick={()=>edit()}><Icon name="plus" size={17}/>{t('m_26787a06df')}</button>{/if}</div>
{#if !loaded}<div class="loading-state"><Icon name="loader"/>{t('m_5bb67fbb6b')}</div>{:else if !session.user}<div class="empty-state"><span class="teaser-icon mint"><Icon name="cellar" size={28}/></span><h2>{t('m_789b1f2805')}</h2><p>{t('m_2680c38d66')}</p><a class="button primary" href="/konto?next=/keller">{t('m_9e897b5365')}<Icon name="right" size={17}/></a></div>{:else}
{#if error&&!open}<p class="error" role="alert" style="margin-bottom:20px">{error}</p>{/if}
{#if bottles.length}<div class="stats-row"><div class="stat-card"><strong>{total}</strong><span>{total===1?'Flasche':'Flaschen'} {t('m_8a400109ac')}</span></div><div class="stat-card"><strong>{bottles.length}</strong><span>{bottles.length===1?'Wein':'verschiedene Weine'}</span></div></div><div class="search-field" style="margin:24px 0"><Icon name="search"/><input aria-label={t('m_0aec167753')} placeholder={t('m_a01a58722d')} bind:value={search}/></div><div class="cellar-list">{#each filtered as bottle}<article class="bottle-card"><Bottle color={bottle.data.style==='Rot'?'#ad687c':bottle.data.style==='Rosé'?'#e4a1a5':'#ccd69d'} label={bottle.data.style.toUpperCase()}/><div class="bottle-details"><small>{bottle.data.style} {bottle.data.year?'· '+bottle.data.year:''}</small><h3>{bottle.data.name}</h3><p>{bottle.data.producer}{bottle.data.region?' · '+bottle.data.region:''}</p>{#if bottle.data.location}<p><Icon name="pin" size={11}/>{bottle.data.location}</p>{/if}<div class="quantity"><button aria-label={'Eine Flasche '+bottle.data.name+' entnehmen'} disabled={busy||bottle.data.quantity===0} onclick={()=>quantity(bottle,-1)}>−</button><strong>{bottle.data.quantity}</strong><button aria-label={'Eine Flasche '+bottle.data.name+' hinzufügen'} disabled={busy} onclick={()=>quantity(bottle,1)}>+</button><span>{t('m_3c7102ee21')}</span><button aria-label={'Details zu '+bottle.data.name+' bearbeiten'} onclick={()=>edit(bottle)}><Icon name="settings" size={16}/></button></div></div></article>{/each}</div>{#if !filtered.length}<p class="muted">{t('m_660e022852')}</p>{/if}<div class="export-row"><button class="text-button" onclick={download}><Icon name="download" size={15}/>{t('m_c95385d84f')}</button></div>{:else}<div class="empty-state"><span class="teaser-icon mint"><Icon name="wine" size={30}/></span><h2>{t('m_c16117b414')}</h2><p>{t('m_a7fea32594')}</p><button class="button primary" onclick={()=>edit()}><Icon name="plus" size={17}/>{t('m_32881f3c45')}</button></div>{/if}{/if}</div>
<Modal bind:open title={id?'Flasche bearbeiten':'Flasche hinzufügen'}><form onsubmit={(e)=>{e.preventDefault();save();}}><div class="form-grid"><label class="wide">{t('m_5ac3639bec')}<input bind:value={form.name} required maxlength="120" placeholder={t('m_b42f8e3db2')}/></label><label class="wide">{t('m_93a3cea85f')}<input bind:value={form.producer} maxlength="120" placeholder={t('m_0a39d73cb5')}/></label><label>{t('m_b4ddfcd481')}<select bind:value={form.style}><option value="Weiß">{t('m_fb938e0288')}</option><option value="Rosé">{t('m_407d70b903')}</option><option value="Rot">{t('m_ab9513c764')}</option><option value="Prickelnd">{t('m_1a9f9c23c7')}</option><option value="Sonstiges">{t('m_aafe07526e')}</option></select></label><label>{t('m_c523435dba')}<input bind:value={form.year} maxlength="12" placeholder={t('m_df84738470')}/></label><label>{t('m_3c7102ee21')}<input type="number" min="0" max="10000" bind:value={form.quantity} required/></label><label>{t('m_0f21717994')}<input bind:value={form.region} maxlength="120" placeholder={t('m_441aac501f')}/></label><label class="wide">{t('m_467f59d620')}<input bind:value={form.location} maxlength="120" placeholder={t('m_7a28433c33')}/></label><label class="wide">{t('m_1bafd328c4')}<textarea rows="3" bind:value={form.memo} maxlength="3000" placeholder={t('m_2eecb24569')}></textarea></label></div>{#if error}<p class="error" role="alert">{error}</p>{/if}<button class="button primary full" disabled={busy}>{busy?'Wird gespeichert …':'Flasche speichern'}<Icon name="check" size={16}/></button>{#if id}<button type="button" class="text-button" style="color:#b36d5d;justify-content:center" onclick={()=>deleteOpen=true}>{t('m_2a989e5bce')}</button>{/if}</form></Modal>
<Modal bind:open={deleteOpen} title={t('m_28784dfc60')}><p class="muted">{t('m_971c1a2519')}{form.name}{t('m_ece47de187')}</p><div class="export-row"><button class="button outline" onclick={()=>deleteOpen=false}>{t('m_99f6d4d377')}</button><button class="button danger" disabled={busy} onclick={remove}>{t('m_50ff2775e9')}</button></div></Modal>
